refentry.refsect1:
&reftitle.description;
public Yaf_Controller_Abstract::__construct
Yaf_Controller_Abstract::__construct es final, lo que significa que no puede ser sobrescrito. Véase en su lugar Yaf_Controller_Abstract::init.

  &reftitle.examples;

   Ejemplo de Yaf_Controller_Abstract::__construct


<?php
class IndexController extends Yaf_Controller_Abstract
{
    // Yaf_Dispatcher llama a __construct() cuando el controlador
    // se instancia durante el despacho, y no debe llamarse a mano
    // ni sobrescribirse. En su lugar se define init():

    public function init() {
        // cuando se ejecuta init(), el despachador ya ha conectado
        // el controlador: la petición, la respuesta y el motor de
        // vistas están todos disponibles
        var_dump($this->getRequest() instanceof Yaf_Request_Abstract);
        var_dump($this->getResponse() instanceof Yaf_Response_Abstract);
        var_dump($this->getView() instanceof Yaf_View_Interface);
    }

    public function indexAction() {
        // ...
    }
}
?>


